def restore_water_followup_text(path,source):
    if str(path)!="src/data/wild_encounters.json":return source
    for key,old in ORIGINAL_WATER_FOLLOWUP.items():
        label,method=key.split("|")
        i=source.index('"'+method+'": {',source.index('"base_label": "'+label+'"'))
        new=BALANCED_WATER_FOLLOWUP[key]
        assert source[i:i+len(new)]==new,key
        source=source[:i]+old+source[i+len(new):]
    return source
def prior_water_followup_source(path):
    return restore_water_followup_text(path,prior_water_batch_source(path).decode("utf-8")).encode("utf-8")
def restore_prior_water_followup_text(path,source):
    return restore_water_followup_text(path,restore_prior_water_batch_text(path,source))
